function money(value?: number | string) { return new Intl.NumberFormat("en-GB", { style: "currency", currency: "GBP", maximumFractionDigits: 0 }).format(Number(value || 0)); }
function when(value?: string) { return value ? new Intl.DateTimeFormat("en-GB", { day: "2-digit", month: "short", year: "numeric", hour:"2-digit", minute:"2-digit" }).format(new Date(value)) : "Not set"; }
function localInput(value?: string) { if (!value) return ""; const d = new Date(value); const p=(n:number)=>String(n).padStart(2,"0"); return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`; }
function iso(value?: string) { return value ? new Date(value).toISOString() : null; }
function suggestedDue(days=3) { const d=new Date(); d.setDate(d.getDate()+days); d.setHours(9,0,0,0); return localInput(d.toISOString()); }
function finishDatePick(e:React.ChangeEvent<HTMLInputElement>, set:(value:string)=>void){set(e.target.value); requestAnimationFrame(()=>e.target.blur());}
function closed(value: string) { return ["completed","declined","cancelled"].includes(value); }
function statusLabel(value: unknown) { return STATUS_META[value as JobStatus]?.label ?? String(value || ""); }
function actionUrgency(value?:string){if(!value)return "none";const due=new Date(value);const now=new Date();const start=new Date(now.getFullYear(),now.getMonth(),now.getDate());const end=new Date(start);end.setDate(end.getDate()+1);return due<start?"overdue":due<end?"today":"future";}
function missingForDraft(d:QuickDraft,config:CrmConfig){const warnings:string[]=[];const won=["confirmed","deposit_requested","deposit_paid","materials_ordered","fabrication","installation_scheduled","in_progress","awaiting_final_payment","completed"].includes(d.status);if(config.modules.quotes&&won&&!d.quotedAmount)warnings.push("Final Quote missing");if(config.modules.costs&&["fabrication","installation_scheduled","in_progress","awaiting_final_payment","completed"].includes(d.status)&&!d.finalCost)warnings.push("Final Cost missing");if(config.modules.scheduling&&d.status==="installation_scheduled"&&!d.scheduledAt)warnings.push("Installation date missing");if(!closed(d.status)&&!d.nextAction)warnings.push("Next Action missing");if(!closed(d.status)&&!d.nextActionAt)warnings.push("Next Action date missing");return warnings;}

const input = "h-10 w-full rounded-xl border border-black/15 bg-white px-3 text-sm outline-none transition focus:border-[#e66a24] focus:ring-2 focus:ring-[#e66a24]/10";
const selectClass = `${input} pr-12`;
function Field({label,children}:{label:string;children:React.ReactNode}) { return <label className="min-w-0"><span className="mb-1.5 block text-[11px] font-black uppercase tracking-[0.08em] text-black/45">{label}</span>{children}</label>; }
function parseMoney(value:unknown){const raw=String(value??"").replace(/,/g,"").trim();if(!raw)return null;const n=Number(raw);return Number.isFinite(n)?n:null;}
function formatMoneyInput(value:string){const raw=String(value||"").replace(/,/g,"").replace(/[^0-9.]/g,"");if(!raw)return "";const parts=raw.split(".");const whole=(parts.shift()||"0").replace(/^0+(?=\d)/,"");const formatted=(whole||"0").replace(/\B(?=(\d{3})+(?!\d))/g,",");return parts.length?`${formatted}.${parts.join("").slice(0,2)}`:formatted;}
function MoneyInput({value,onChange,name}:{value:string;onChange:(v:string)=>void;name?:string}) { return <div className="relative"><span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 font-bold text-black/45">£</span><input name={name} type="text" inputMode="decimal" value={formatMoneyInput(value)} onChange={e=>onChange(e.target.value.replace(/,/g,""))} className={`${input} pl-7`}/></div>; }
function MoneyFormInput({name,defaultValue}:{name:string;defaultValue:unknown}){return <div className="relative"><span className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 font-bold text-black/45">£</span><input name={name} type="text" inputMode="decimal" defaultValue={formatMoneyInput(String(defaultValue??""))} onInput={e=>{const el=e.currentTarget;const pos=el.selectionStart;const before=el.value;el.value=formatMoneyInput(el.value);if(pos!=null){const delta=el.value.length-before.length;requestAnimationFrame(()=>el.setSelectionRange(Math.max(0,pos+delta),Math.max(0,pos+delta)));}}} className={`${input} pl-7`}/></div>}
