  function openQuick(j:any){if(editingRef===j.reference){cancelQuick();return;}setEditingRef(j.reference);setEditUpdatedAt(j.updatedAt||null);setRemoteChanged(false);setRemoteChangedBy(null);setCustomType("");setQuickFull(j.latestQuote?{quotes:[j.latestQuote]}:null);setQuoteOpen(false);setQuoteScope("");setQuoteExclusions("");setDraft({firstName:j.isPlaceholder?"":j.firstName||"",lastName:j.isPlaceholder?"":j.lastName||"",phone:j.phone||"",email:j.email||"",siteAddressLine1:j.siteAddressLine1||"",sitePostcode:j.sitePostcode||"",jobTypes:j.isPlaceholder?[]:(j.jobTypes||[j.jobType].filter(Boolean)),status:j.isPlaceholder?"awaiting_information":j.status,manager:j.isPlaceholder?"":j.manager||"",source:j.source||"",finishes:Array.isArray(j.finishes)?j.finishes:[],preliminaryEstimate:String(j.preliminaryEstimate??""),quotedAmount:String(j.quotedAmount??""),estimatedCost:String(j.estimatedCost??""),finalCost:String(j.finalCost??""),jobNotes:j.internalNotes||"",dimensions:j.dimensions||"",material:j.material||"",colour:j.colour||"",customerRequirements:j.customerRequirements||"",scheduledAt:localInput(j.scheduledAt),nextAction:j.collectionRequired?"Collect outstanding balance":closed(j.status)?"":(j.status==="awaiting_customer"&&j.nextAction==="Await customer decision"?"":j.nextAction)||"",nextActionAt:closed(j.status)?"":localInput(j.nextActionAt),nextActionAssignee:closed(j.status)?"":j.nextActionAssignee||""});void loadQuickFull(j.reference);}
