  function localActivity(j:any,savedDraft:QuickDraft|null,savedStatus:string,savedNext:any){
    if(!savedDraft)return;
    const actor=String(admin?.name||admin?.display_name||admin?.displayName||admin?.email||"BMS user");
    const changes:string[]=[];
    const nextWasExplicit=String(savedDraft.nextAction||"")!==String(j.nextAction||"");
    if(savedStatus!==String(j.status||""))changes.push(`${actor} changed status to ${statusLabel(savedStatus)}`);
    if(nextWasExplicit&&String(savedNext||"")!==String(j.nextAction||""))changes.push(`${actor} changed next action to ${savedNext||"none"}`);
    if(String(savedDraft.manager||"")!==String(j.manager||""))changes.push(`${actor} changed assigned to ${savedDraft.manager||"none"}`);
    const oldTypes=JSON.stringify(Array.isArray(j.jobTypes)&&j.jobTypes.length?j.jobTypes:(j.jobType?[j.jobType]:[]));
    const newTypes=JSON.stringify(savedDraft.jobTypes||[]);
    if(oldTypes!==newTypes)changes.push(`${actor} changed work type to ${(savedDraft.jobTypes||[]).join(", ")||"none"}`);
    if(changes.length)setActivities(prev=>[...changes.map((summary,i)=>({id:`local-${Date.now()}-${i}`,job_id:j.id,summary,occurred_at:new Date().toISOString(),job:{reference:j.reference},mj_jobs:{reference:j.reference},source:"activity"})),...prev]);
  }

  async function saveQuick(j:any,overrides:Record<string,unknown>={},saveOpenQuote=false){
    if(!draft&&Object.keys(overrides).length===0)return;
    if(remoteChanged){setFlash("This job was updated by someone else. Load their changes before saving.");return;}
    const savedDraft=draft?{...draft}:null;
    const previousStatus=String(j.status||"");
    // Update the visible job immediately. The server save then confirms it.
    // If the save fails, reload the authoritative tenant state.
    if(savedDraft){
      const optimisticUpdatedAt=new Date().toISOString();
      setJobs(prev=>prev.map(x=>x.reference===j.reference?{...x,status:savedDraft.status,nextAction:closed(savedDraft.status)?null:(savedDraft.nextAction||null),nextActionAt:closed(savedDraft.status)?null:iso(savedDraft.nextActionAt),updatedAt:optimisticUpdatedAt,firstName:savedDraft.firstName,lastName:savedDraft.lastName,customerName:[savedDraft.firstName,savedDraft.lastName].filter(Boolean).join(" "),phone:savedDraft.phone,email:savedDraft.email,siteAddressLine1:savedDraft.siteAddressLine1,sitePostcode:savedDraft.sitePostcode,address:[savedDraft.siteAddressLine1,savedDraft.sitePostcode].filter(Boolean).join(", "),preliminaryEstimate:savedDraft.preliminaryEstimate===""?null:parseMoney(savedDraft.preliminaryEstimate),quotedAmount:savedDraft.quotedAmount===""?null:parseMoney(savedDraft.quotedAmount),estimatedCost:savedDraft.estimatedCost===""?null:parseMoney(savedDraft.estimatedCost),finalCost:savedDraft.finalCost===""?null:parseMoney(savedDraft.finalCost),jobTypes:savedDraft.jobTypes,jobType:savedDraft.jobTypes[0]||x.jobType,manager:savedDraft.manager,source:savedDraft.source}:x));
    }
    setSavingRef(j.reference);
    const customer:Record<string,unknown>={},job:Record<string,unknown>={...overrides};
    if(savedDraft){
      customer.first_name=savedDraft.firstName||(j.isPlaceholder?"Details TBC":null);customer.last_name=savedDraft.lastName||null;customer.phone=savedDraft.phone||null;customer.email=savedDraft.email||null;
      job.site_address_line_1=savedDraft.siteAddressLine1||null;job.site_postcode=savedDraft.sitePostcode||null;job.job_types=savedDraft.jobTypes;job.job_type=savedDraft.jobTypes[0]||null;job.status=savedDraft.status;
      job.manager=savedDraft.manager||null;job.enquiry_source=savedDraft.source||null;if(crmConfig.modules.finishes)job.finishes=savedDraft.finishes;
      if(crmConfig.modules.quotes){job.preliminary_estimate=savedDraft.preliminaryEstimate===""?null:parseMoney(savedDraft.preliminaryEstimate);job.quoted_amount=savedDraft.quotedAmount===""?null:parseMoney(savedDraft.quotedAmount);}
      job.internal_notes=savedDraft.jobNotes||null;job.dimensions=savedDraft.dimensions||null;job.material=savedDraft.material||null;job.colour=savedDraft.colour||null;job.customer_requirements=savedDraft.customerRequirements||null;
      if(crmConfig.modules.scheduling)job.scheduled_at=iso(savedDraft.scheduledAt);
      if(closed(savedDraft.status)){job.next_action=null;job.next_action_at=null;job.next_action_assignee=null;}else{job.next_action=savedDraft.nextAction||null;job.next_action_at=iso(savedDraft.nextActionAt);job.next_action_assignee=savedDraft.nextActionAssignee||null;}
      if(j.isPlaceholder&&(savedDraft.firstName||savedDraft.lastName||savedDraft.siteAddressLine1||savedDraft.jobTypes.length||savedDraft.preliminaryEstimate||savedDraft.quotedAmount))job.internal_notes=null;
    }
    const res=await fetch(`/api/jobs/${encodeURIComponent(j.reference)}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({customer,job,explicit_next_action:Boolean(savedDraft&&String(savedDraft.nextAction||"")!==String(j.nextAction||"")),explicit_next_action_at:Boolean(savedDraft&&String(savedDraft.nextActionAt||"")!==String(j.nextActionAt||""))})});
    const body=await res.json().catch(()=>({}));
    if(!res.ok){setSavingRef(null);setFlash(body.error||`Could not save ${j.reference}`);void load();return;}
    if(!body?.verified){setSavingRef(null);setFlash(`Could not verify that ${j.reference} saved. Please try again.`);void load();return;}
    if(savedDraft&&crmConfig.modules.costs&&permissions.includes("view_costs_profit")){
      const oldEstimated=j.estimatedCost==null?"":String(j.estimatedCost),oldActual=j.finalCost==null?"":String(j.finalCost);
      if(String(savedDraft.estimatedCost)!==oldEstimated||String(savedDraft.finalCost)!==oldActual){
        const costRes=await fetch(`/api/jobs/${encodeURIComponent(j.reference)}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({type:"cost_summary",estimated_amount:savedDraft.estimatedCost===""?null:parseMoney(savedDraft.estimatedCost),actual_amount:savedDraft.finalCost===""?null:parseMoney(savedDraft.finalCost)})});
        if(!costRes.ok){setSavingRef(null);setFlash("The job was saved. The cost figures need another try.");return;}
      }
    }
    if(saveOpenQuote&&quoteOpen&&quickFull?.quotes?.[0]){const form=document.getElementById(`quick-quote-form-${j.reference}`) as HTMLFormElement|null;if(form){const ok=await saveQuickQuoteForm(j,form,false);if(!ok){setSavingRef(null);return;}}}
    const savedStatus=String(body?.job?.status||savedDraft?.status||j.status||"");
    const savedNext=body?.job?.next_action??savedDraft?.nextAction??j.nextAction;
    const savedNextAt=body?.job?.next_action_at??(savedDraft?.nextActionAt?iso(savedDraft.nextActionAt):j.nextActionAt);
    const savedUpdated=body?.job?.updated_at||new Date().toISOString();
    setJobs(prev=>prev.map(x=>x.reference===j.reference?{...x,status:savedStatus,nextAction:savedNext,nextActionAt:savedNextAt,updatedAt:savedUpdated,...(savedDraft?{firstName:savedDraft.firstName,lastName:savedDraft.lastName,customerName:[savedDraft.firstName,savedDraft.lastName].filter(Boolean).join(" "),phone:savedDraft.phone,email:savedDraft.email,siteAddressLine1:savedDraft.siteAddressLine1,sitePostcode:savedDraft.sitePostcode,address:[savedDraft.siteAddressLine1,savedDraft.sitePostcode].filter(Boolean).join(", "),preliminaryEstimate:savedDraft.preliminaryEstimate===""?null:parseMoney(savedDraft.preliminaryEstimate),quotedAmount:savedDraft.quotedAmount===""?null:parseMoney(savedDraft.quotedAmount),estimatedCost:savedDraft.estimatedCost===""?null:parseMoney(savedDraft.estimatedCost),finalCost:savedDraft.finalCost===""?null:parseMoney(savedDraft.finalCost),jobTypes:savedDraft.jobTypes,jobType:savedDraft.jobTypes[0]||x.jobType,manager:savedDraft.manager,source:savedDraft.source}:{} )}:x));
    if(savedDraft)setDraft(d=>d?{...d,status:savedStatus as JobStatus}:d);
    const demo=Boolean(body?.demo);
    if(demo){
      const actor="Test user",changes:string[]=[];
      if(savedDraft&&savedStatus!==j.status)changes.push(`${actor} changed status to ${statusLabel(savedStatus)}`);
      if(savedDraft&&String(savedNext||"")!==String(j.nextAction||""))changes.push(`${actor} changed next action to ${savedNext||"none"}`);
      if(savedDraft&&savedDraft.firstName+" "+savedDraft.lastName!==String(j.customerName||""))changes.push(`${actor} changed customer name to ${savedDraft.firstName} ${savedDraft.lastName}`.trim());
      if(changes.length)setActivities(prev=>[...changes.map((summary,i)=>({id:`demo-local-${Date.now()}-${i}`,job_id:j.id,summary,occurred_at:new Date().toISOString(),mj_jobs:{reference:j.reference},source:"activity"})),...prev]);
      setTimeout(()=>setJobs(prev=>prev.map(x=>x.reference===j.reference?j:x)),5000);
    }else{
      // The PATCH response is authoritative. Update both the row and activity UI
      // immediately; server refresh is background reconciliation only.
      setQuickFull((q:any)=>q?{...q,job:{...(q.job||{}),...(body?.job||{})},customer:{...(q.customer||{}),...(body?.customer||{})}}:q);
      if(body?.job?.updated_at)setEditUpdatedAt(body.job.updated_at);
      localActivity(j,savedDraft,savedStatus,savedNext);
      window.setTimeout(()=>{void Promise.all([loadQuickFull(j.reference),load()]).catch(()=>{});},450);
    }
    setSavingRef(null);setRemoteChanged(false);setRemoteChangedBy(null);setFlash(`✓ ${j.reference} saved`);setTimeout(()=>setFlash(""),2600);
  }
  async function postAction(reference:string,payload:Record<string,unknown>){setSavingRef(reference);const res=await fetch(`/api/jobs/${encodeURIComponent(reference)}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const body=await res.json().catch(()=>({}));setSavingRef(null);if(!res.ok){setFlash(body.error||"Could not save");return false;}await load();setFlash(`${reference} updated`);setTimeout(()=>setFlash(""),1800);return true;}
  async function editPayment(reference:string,p:any){const paymentType=await askInput("Edit payment","Payment type",String(p.payment_type||"Payment"));if(paymentType===null)return;const amountRaw=await askInput("Edit payment","Payment amount (£)",String(p.amount??""),"number");if(amountRaw===null)return;const amount=Number(amountRaw);if(!Number.isFinite(amount)||amount<0){setFlash("Enter a valid payment amount");return;}const currentDate=p.paid_at?new Date(p.paid_at).toISOString().slice(0,10):"";const dateRaw=await askInput("Edit payment","Date received",currentDate,"date");if(dateRaw===null)return;const paidAt=dateRaw?new Date(`${dateRaw}T12:00:00`).toISOString():null;const res=await fetch(`/api/jobs/${encodeURIComponent(reference)}/payments/${encodeURIComponent(p.id)}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({payment_type:paymentType,amount,paid_at:paidAt})});const body=await res.json().catch(()=>({}));if(!res.ok){setFlash(body.error||"Could not update payment");return;}await load();setFlash("Payment updated");setTimeout(()=>setFlash(""),1800);}
  async function deletePayment(reference:string,p:any){if(!(await ask("Delete payment",`Delete ${p.payment_type||"payment"} of ${money(p.amount)}?`,"Delete payment",true)))return;const res=await fetch(`/api/jobs/${encodeURIComponent(reference)}/payments/${encodeURIComponent(p.id)}`,{method:"DELETE"});const body=await res.json().catch(()=>({}));if(!res.ok){setFlash(body.error||"Could not delete payment");return;}await load();setFlash("Payment deleted");setTimeout(()=>setFlash(""),1800);}
  async function writeOffBalance(j:any){const max=Number(j.balanceOutstanding||0);if(!(max>0))return;const amountRaw=await askInput("Write off balance","Amount to write off (£)",String(max),"number");if(amountRaw===null)return;const amount=Number(amountRaw);if(!(amount>0)||amount>max){setFlash(`Write-off must be between £0 and ${money(max)}`);return;}const reason=await askInput("Write off balance","Reason for write-off");if(reason===null||!reason.trim())return;const res=await fetch(`/api/jobs/${encodeURIComponent(j.reference)}/write-off`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({amount,reason:reason.trim()})});const body=await res.json().catch(()=>({}));if(!res.ok){setFlash(body.error||"Could not write off balance");return;}await load();setFlash(`${money(amount)} written off`);setTimeout(()=>setFlash(""),1800);}
  async function recordSubPayment(reference:string,assignmentId:string,e:FormEvent<HTMLFormElement>){e.preventDefault();const fd=new FormData(e.currentTarget),amount=Number(fd.get("amount")||0);if(!amount)return;const res=await fetch(`/api/jobs/${encodeURIComponent(reference)}/subcontractors/${encodeURIComponent(assignmentId)}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({add_payment:amount,paid_at:fd.get("paid_at")?new Date(String(fd.get("paid_at"))).toISOString():new Date().toISOString()})});if(!res.ok){setFlash("Could not record subcontractor payment");return;}await load();e.currentTarget.reset();}
  async function removeAssignment(reference:string,assignmentId:string,personName:string){if(!(await ask("Remove from job",`Remove ${personName} from this job?`,"Remove",true)))return;setRemovingAssignment(assignmentId);const res=await fetch(`/api/jobs/${encodeURIComponent(reference)}/subcontractors/${encodeURIComponent(assignmentId)}`,{method:"DELETE"});setRemovingAssignment(null);if(!res.ok){const body=await res.json().catch(()=>({}));setFlash(body.error||"Could not remove assignment");return;}await load();setFlash(`${personName} removed`);setTimeout(()=>setFlash(""),1800);}
  function suggestedQuoteScope(j:any){if(!draft)return "";return [draft.jobTypes.length?`Supply and install ${draft.jobTypes.join(" and ").toLowerCase()} to the agreed site.`:"",draft.dimensions?`Approximate dimensions: ${draft.dimensions}.`:"",draft.material?`Manufactured in ${draft.material}.`:"",draft.finishes.length?`Finish: ${draft.finishes.join(" and ")}${draft.colour?`, ${draft.colour}`:""}.`:"",draft.customerRequirements||""].filter(Boolean).join("\n\n");}
  async function createQuickQuote(j:any,e:FormEvent<HTMLFormElement>){e.preventDefault();await saveQuickQuoteForm(j,e.currentTarget,true);}
  async function saveQuickQuoteForm(j:any,form:HTMLFormElement,openPdf=true){if(!draft)return false;const fd=new FormData(form);const amount=parseMoney(fd.get("amount"))??parseMoney(draft.quotedAmount)??parseMoney(draft.preliminaryEstimate)??0,scope=quoteScope.trim();const critical:string[]=[];if(!(amount>0))critical.push("quote price");if(!scope)critical.push("job description / scope");if(critical.length&&!(await ask("Quote information missing",`This quote is missing ${critical.join(" and ")}. Create it anyway?`,"Create anyway")))return;const existingQuote=quickFull?.quotes?.[0]||null;setQuoteBusy(true);setRemoteChanged(false);setRemoteChangedBy(null);setFlash(existingQuote?"Saving quote changes...":"Creating quote...");const payload={type:"quote",quote_id:existingQuote?.id||undefined,vat_rate:Number(fd.get("vat_rate")||0),amount,deposit_amount:parseMoney(fd.get("deposit_amount")),lead_time:String(fd.get("lead_time")||"")||null,valid_until:String(fd.get("valid_until")||"")||null,scope_text:scope,exclusions:quoteExclusions.trim()||null};const res=await fetch(`/api/jobs/${encodeURIComponent(j.reference)}`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const body=await res.json().catch(()=>({}));if(!res.ok){setQuoteBusy(false);setFlash(body.error||"Could not save quote");return false;}if(!body.item?.id){setQuoteBusy(false);setFlash("Quote was not saved. No quote record was returned.");return false;}setQuickFull((q:any)=>({...q,quotes:[body.item,...((q?.quotes||[]).filter((x:any)=>x.id!==body.item.id))]}));const quoteId=body.item.id;setFlash("Quote saved");setQuoteBusy(false);setRemoteChanged(false);setRemoteChangedBy(null);setDraft(d=>d?{...d,quotedAmount:String(payload.amount),status:"quote_preparing",nextAction:"Send quote"}:d);setQuickFull((q:any)=>q?{...q,quotes:[body.item,...(q.quotes||[]).filter((x:any)=>x.id!==body.item?.id)]}:q);const refreshedQuote=await loadQuickFull(j.reference);if(refreshedQuote?.job?.updated_at)setEditUpdatedAt(refreshedQuote.job.updated_at);await load();setQuoteOpen(false);setFlash(`Quote V${body.item?.version||""} saved. Use Open / send to view it.`);if(openPdf&&quoteId)window.open(`/jobs/${encodeURIComponent(j.reference)}/quote/${encodeURIComponent(quoteId)}`,"_blank","noopener,noreferrer");setTimeout(()=>setFlash(""),2600);return true;}
  async function createInvoiceDirect(j:any){if(!draft)return;const amount=Number(draft.quotedAmount||0);const description=String(draft.customerRequirements||"").trim()||String((draft.jobTypes||[]).join(" + ")).trim();const missing:string[]=[];if(!(amount>0))missing.push("Final Quote");if(!description)missing.push("job description");if(missing.length&&!(await ask("Invoice information missing",`This invoice is missing ${missing.join(" and ")}. Continue anyway?`,"Continue")))return;if(!(amount>0)){setFlash("Enter the Final Quote before creating the invoice");return;}setInvoiceBusy(true);await saveQuick(j);const res=await fetch(`/api/jobs/${encodeURIComponent(j.reference)}/xero`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"create",amount,description,vat_rate:crmConfig.businessDetails.vatRegistered?crmConfig.businessDetails.defaultVatRate:0})});const body=await res.json().catch(()=>({}));setInvoiceBusy(false);if(!res.ok){setFlash(body.error||"Could not create invoice");return;}setFlash("Draft invoice created in Xero");window.location.href=`/jobs/${encodeURIComponent(j.reference)}/xero`;}
