  const photoLightbox=photoViewer?<div className="fixed inset-0 z-[210] flex items-center justify-center bg-black/80 p-3 sm:p-6" onClick={()=>setPhotoViewer(null)}><div className="relative flex max-h-full max-w-5xl items-center justify-center" onClick={e=>e.stopPropagation()}><img src={photoViewer.url} alt={photoViewer.name} className="max-h-[88vh] max-w-full rounded-xl object-contain shadow-2xl"/><button type="button" onClick={()=>setPhotoViewer(null)} aria-label="Close photo" className="absolute right-2 top-2 flex h-10 w-10 items-center justify-center rounded-full bg-white/95 text-2xl font-black leading-none text-black shadow-lg">×</button></div></div>:null;

